    const text=`INTERLIS ${version}; MODEL F AT "https://example.org" VERSION "1" = TOPIC T=CLASS C=e:(red,green) ORDERED; MANDATORY CONSTRAINT e==#red AND INTERLIS.len("abc")>0; END C; END T; END F.`;
