  for(const c of e2NamedCollectionCases) await verify(c.text,c.expected);
  for(const reverse of [false,true]) {
    const baseId=reverse?'memory:/z-base.ili':'memory:/a-base.ili';
    const useId=reverse?'memory:/a-use.ili':'memory:/z-use.ili';
    const baseText='INTERLIS 2.4;MODEL Base AT "https://example.org" VERSION "1"=DOMAIN Label=TEXT*20;RequiredLabel EXTENDS Label=MANDATORY;TOPIC Other=CLASS Wrong=END Wrong;END Other;END Base.';
    const useText='INTERLIS 2.4;MODEL F AT "https://example.org" VERSION "1"=IMPORTS Base;TOPIC T=CLASS C=labels:LIST {1..3} OF Base.RequiredLabel;identifiers:BAG OF INTERLIS.UUIDOID;END C;END T;END F.';
    await verifySources([{sourceId:baseId,text:baseText},{sourceId:useId,text:useText}],'succeeded',['F'],async(sessionId,compiled)=>{
      const inspect=async(snapshot,revision)=>{
        const declaration=await call('query',sessionId,{snapshotId:snapshot,query:{kind:'symbolAt',sourceId:baseId,revision:'1',startOffset:baseText.indexOf('RequiredLabel'),endOffset:baseText.indexOf('RequiredLabel')}});
        const offset=useText.indexOf('Base.RequiredLabel')+5;
        const query={sourceId:useId,revision,startOffset:offset,endOffset:offset};
        const use=await call('query',sessionId,{snapshotId:snapshot,query:{...query,kind:'symbolAt'}});
        const definition=await call('query',sessionId,{snapshotId:snapshot,query:{...query,kind:'definition'}});
        if(declaration.kind!=='known' || use.kind!=='known' || definition.kind!=='definition' || declaration.symbolId!==use.symbolId || use.symbolId!==definition.symbolId)throw new Error('Collection element identity mismatch '+JSON.stringify({declaration,use,definition}));
      };
      await inspect(compiled.snapshotId,'1');
      let updated=await call('updateSource',sessionId,{sourceId:useId,expectation:{kind:'at',revision:'1'},change:{kind:'replace',text:useText.replace('OF Base.RequiredLabel','OF Base.Other.Wrong')}});
      const rejected=await call('compile',sessionId,{expectedWorkspaceRevision:updated.workspaceRevision,roots:[{kind:'byName',modelName:'F'}]});
      if(rejected.outcome!=='rejected')throw new Error('Collection accepted class '+JSON.stringify(rejected));
      updated=await call('updateSource',sessionId,{sourceId:useId,expectation:{kind:'at',revision:updated.sourceRevision},change:{kind:'replace',text:useText}});
      const recovered=await call('compile',sessionId,{expectedWorkspaceRevision:updated.workspaceRevision,roots:[{kind:'byName',modelName:'F'}]});
      if(recovered.outcome!=='succeeded')throw new Error('Collection edit did not recover '+JSON.stringify(recovered));
      await inspect(recovered.snapshotId,updated.sourceRevision);
    });
  }
